"""
SQLAlchemy ORM model for analytics.mart__item_mapping_timeline table.
"""

from sqlalchemy import Column, String, Integer, DateTime, Date, Boolean
from mpi_backend.database import Base


class ItemMappingTimelineMart(Base):
    """
    ORM model for the analytics.mart__item_mapping_timeline dbt mart.

    This table is managed by dbt — do not modify via ORM.
    One row per (supplier_item_ids, supplier_id).
    """
    __tablename__ = "mart__item_mapping_timeline"
    __table_args__ = {"schema": "analytics"}

    # Surrogate Primary Key (Generated by dbt)
    id = Column(String, primary_key=True)

    supplier_item_ids = Column(String, index=True)
    supplier_id = Column(Integer)
    supplier = Column(String)

    # Event details
    mapping_type = Column(String)
    mpi_code = Column(String)
    sheet_title = Column(String)
    recorded_at = Column(DateTime)
    is_delete_record = Column(Boolean, default=False)

    # Audit
    mart_refreshed_at = Column(DateTime)
